class Scale:
    SHARPS = ['A', 'A#', 'B', 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#']
    FLATS  = ['A', 'Bb', 'B', 'C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab']

    # Keys (by tonic) that conventionally use sharps or flats when ascending.
    # Major keys (uppercase tonic) and minor keys (lowercase tonic) are distinct.
    MAJOR_SHARPS = {'G', 'D', 'A', 'E', 'B', 'F#', 'C#', 'C'}  # include C as special-case (natural)
    MAJOR_FLATS  = {'F', 'Bb', 'Eb', 'Ab', 'Db', 'Gb'}
    MINOR_SHARPS = {'a', 'e', 'b', 'f#', 'c#', 'g#', 'd#'}     # include 'a' (natural) as following sharps
    MINOR_FLATS  = {'d', 'g', 'c', 'f', 'bb', 'eb'}

    INTERVAL_STEPS = {'m': 1, 'M': 2, 'A': 3}

    def __init__(self, tonic):
        # Normalize input tonic and remember original case for major/minor decision.
        t = tonic.strip()
        self._is_minor = t[0].islower()
        # Normalize accidental characters: accept '#' or '♯' for sharp, 'b' or '♭' for flat.
        rest = t[1:] if len(t) > 1 else ''
        if rest:
            r = rest[0]
            if r in ('#', '♯'):
                rest = '#'
            elif r in ('b', '♭', 'B'):
                rest = 'b'
            else:
                rest = rest.lower()
        # canonical has uppercase letter and accidental (if any) where flat uses lowercase 'b'
        self.tonic = t[0].upper() + rest

        # Decide whether to use sharps or flats for this tonic.
        if self._is_minor:
            key_for_lookup = self.tonic.lower()
            self.use_sharps = key_for_lookup in Scale.MINOR_SHARPS
        else:
            key_for_lookup = self.tonic
            self.use_sharps = key_for_lookup in Scale.MAJOR_SHARPS

        # Default to sharps if the tonic wasn't found in either list
        if not (self.use_sharps or
                (self._is_minor and key_for_lookup in Scale.MINOR_FLATS) or
                (not self._is_minor and key_for_lookup in Scale.MAJOR_FLATS)):
            self.use_sharps = True

    def chromatic(self):
        # Choose appropriate 12-tone representation
        base = Scale.SHARPS if self.use_sharps else Scale.FLATS
        # Find the starting index for the tonic in the chosen representation
        try:
            i = base.index(self.tonic)
        except ValueError:
            # As a fallback, try matching ignoring accidental case (rare)
            # This handles input like 'bb' -> 'Bb' or similar not found due to unexpected formatting.
            # Attempt a best-effort match by comparing uppercase letters and accidentals normalized.
            def normalize(n):
                return n[0].upper() + (n[1:] if len(n) > 1 else '')
            found = None
            for idx, note in enumerate(base):
                if normalize(note) == normalize(self.tonic):
                    found = idx
                    break
            if found is None:
                raise
            i = found

        # Rotate so tonic is first and return the 12-note chromatic scale
        return base[i:] + base[:i]

    def interval(self, intervals):
        chrom = self.chromatic()
        result = [chrom[0]]
        idx = 0
        for iv in intervals:
            step = Scale.INTERVAL_STEPS.get(iv)
            if step is None:
                raise ValueError(f"Invalid interval character: {iv}")
            idx = (idx + step) % 12
            result.append(chrom[idx])
        return result
